import{mergeGeometries}from'three/addons/utils/BufferGeometryUtils.js';
import * as T from 'three';
import {block,VoxelAssetFactory} from './VoxelAssetFactory.js';

// Transparent floor decals: no rectangular signs floating over the play space.
export function label(text){
 const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;
 const ctx=canvas.getContext('2d');ctx.clearRect(0,0,256,256);
 ctx.font='80px "Arial Rounded MT Bold", system-ui';ctx.textAlign='center';ctx.textBaseline='middle';
 ctx.fillText(text.match(/\p{Extended_Pictographic}/u)?.[0]||'⭐',128,128);
 const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;
 const decal=new T.Mesh(new T.PlaneGeometry(1.6,1.6),new T.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2}));
 decal.rotation.x=-Math.PI/2;return decal;
}
const neon=(color)=>new T.MeshStandardMaterial({color,emissive:color,emissiveIntensity:1.5,roughness:.3});
function ring(parent,r,y,color){const m=new T.Mesh(new T.TorusGeometry(r,.065,8,48),neon(color));m.rotation.x=Math.PI/2;m.position.y=y;parent.add(m);return m}
function studs(w,d){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,128,128);for(const a of [32,96])for(const b of [32,96]){x.fillStyle='#acc69c';x.beginPath();x.arc(a,b,18,0,7);x.fill();x.fillStyle='#edf7df';x.beginPath();x.arc(a,b-3,16,0,7);x.fill()}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(w/3,d/3);t.anisotropy=4;return t}
export class MapPropBuilder{
 constructor(group){this.group=group;this.solids=[];this.pads=[];this.animated=[]}
 platform(x,y,z,w,d,color=0x55ce52){const m=block(this.group,color,x,y,z,w,.6,d);if(w>40&&d>40){const top=new T.Mesh(new T.PlaneGeometry(w,d),new T.MeshStandardMaterial({color,map:studs(w,d),roughness:.9}));top.rotation.x=-Math.PI/2;top.position.set(x,y+.306,z);top.receiveShadow=true;this.group.add(top)}this.solids.push({x,z,y:y+.3,w,d});return m}
 pad(x,z,icon,color,fn){const g=new T.Group();g.position.set(x,0,z);const base=new T.Mesh(new T.CylinderGeometry(1.5,1.65,.22,48),new T.MeshStandardMaterial({color,roughness:.3}));base.position.y=.14;base.receiveShadow=true;g.add(base);const halo=ring(g,1.46,.29,color);const l=label(icon);l.position.y=.3;g.add(l);this.group.add(g);this.pads.push({x,z,fn,cool:0,hint:icon});this.animated.push(t=>halo.material.emissiveIntensity=1.1+Math.sin(t*2)*.25);return g}
 decorate(){const scenery=new T.Group();this.group.add(scenery);for(let i=0;i<30;i++){const t=VoxelAssetFactory.tree();t.position.set(Math.sin(i*2.4)*(30+i%4*5),0,Math.cos(i*2.4)*(30+i%4*5));scenery.add(t)}const colors=[0x35bffa,0xffca38,0xff6eb1,0x9177fa];for(let i=0;i<26;i++){const x=-38+i*3;block(scenery,colors[i%4],x,.9,-36,.26,1.8,.26);block(scenery,colors[i%4],x+1.5,.6,-36,2.9,.18,.18);block(scenery,colors[i%4],x+1.5,1.3,-36,2.9,.18,.18)}for(let i=0;i<20;i++){block(scenery,0xf7edce,-1.65,.08,-29+i*3,3,.12,2.8);block(scenery,0xfff7e3,1.65,.08,-29+i*3,3,.12,2.8)}scenery.updateMatrixWorld(true);const batches=new Map();scenery.traverse(o=>{if(o.isMesh){const key=o.material.uuid;if(!batches.has(key))batches.set(key,{material:o.material,parts:[]});batches.get(key).parts.push(o.geometry.clone().applyMatrix4(o.matrixWorld))}});scenery.clear();for(const {material,parts}of batches.values()){const geo=mergeGeometries(parts);parts.forEach(p=>p.dispose());if(geo){const mesh=new T.Mesh(geo,material);mesh.castShadow=true;mesh.receiveShadow=true;scenery.add(mesh)}}}
 machine(x,z,name){const g=new T.Group();g.position.set(x,0,z);const gold=name.includes('👑'),merge=name.includes('+'),color=gold?0xffbc32:merge?0x9961ff:0xff57ae;block(g,0x38348c,0,.22,0,4.8,.44,3.1);block(g,color,0,.46,0,4.5,.15,2.8);for(const a of [-1.15,1.15]){const tube=new T.Group();tube.position.x=a;g.add(tube);const glass=new T.Mesh(new T.CapsuleGeometry(.72,1.45,8,24),new T.MeshPhysicalMaterial({color:0x8aefff,transparent:true,opacity:.23,roughness:.08,metalness:.05,side:T.FrontSide,depthWrite:false}));glass.position.y=1.8;tube.add(glass);ring(tube,.76,.65,color);ring(tube,.76,2.95,color);block(tube,0x43399b,0,3.05,0,1.7,.22,1.7);const egg=new T.Group();const shell=new T.Mesh(new T.SphereGeometry(.48,24,16),new T.MeshStandardMaterial({color:gold?0xffd14a:a<0?0xff87cd:0x68e7f8,roughness:.3}));shell.scale.y=1.3;egg.add(shell);for(let i=0;i<9;i++){const dot=new T.Mesh(new T.SphereGeometry(.09,8,6),new T.MeshStandardMaterial({color:i%2?0xffffff:0xffe655}));const angle=i*2.4;dot.position.set(Math.sin(angle)*.43,Math.sin(i)*.4,Math.cos(angle)*.43);egg.add(dot)}egg.position.y=1.65;tube.add(egg);this.animated.push((t,calm)=>{const active=t<(g.userData.activeUntil||0);egg.rotation.z=active?Math.sin(t*24)*(calm?.04:.13):0;egg.rotation.y=t*.35;egg.position.y=1.65+Math.sin(t*1.7+a)* (calm?.035:.1)})}if(merge){block(g,0xffde65,0,1.2,0,.35,.35,1);const core=new T.Mesh(new T.SphereGeometry(.5,20,12),neon(0xb96dff));core.position.y=1.8;g.add(core);for(let i=0;i<3;i++){const tesla=new T.Mesh(new T.TorusGeometry(.65+i*.12,.035,6,32),neon(i%2?0xffd655:0x62efff));tesla.position.y=1.8;g.add(tesla);this.animated.push((t,calm)=>{tesla.rotation.set(t*.5+i,t*.3+i,Math.PI/3);tesla.material.emissiveIntensity=t<(g.userData.activeUntil||0)?(calm?1.5:3):1})}}this.group.add(g);return g}
 treadmill(x,z){const g=new T.Group();g.position.set(x,0,z);block(g,0x35308d,0,.3,0,3.3,.6,6.5);block(g,0x163b69,0,.67,0,2.7,.15,5.8);for(let i=0;i<13;i++){const m=new T.Mesh(new T.CylinderGeometry(.17,.17,2.6,12),new T.MeshStandardMaterial({color:i%2?0x256a9a:0x4eabdc,metalness:.4,roughness:.3}));m.rotation.z=Math.PI/2;m.position.set(0,.77,-2.7+i*.45);g.add(m);this.animated.push(t=>m.rotation.x=t*5)}for(const side of [-1,1]){block(g,0x436bff,side*1.6,.62,0,.38,.6,6);const glow=block(g,0x32f6ff,side*1.6,.98,0,.16,.1,5.8);glow.material=neon(0x20e9ff);this.animated.push(()=>{const color=[0x20e9ff,0x31ffaa,0xffd94d,0xff70ce,0xa478ff,0x8ffff5][g.userData.level||0];glow.material.color.setHex(color);glow.material.emissive.setHex(color)});block(g,0x975cff,side*1.55,1.45,-1.9,.16,1.4,.16);block(g,0x6ceeff,side*1.55,2.1,-1.2,.16,.15,1.5)}block(g,0x6257e3,0,2.05,-2,2,.9,.18);const screen=block(g,0x1affbd,0,2.08,-1.88,1.5,.5,.05);screen.material=neon(0x20ffbd);for(let i=0;i<4;i++){const arrow=new T.Group();for(const side of [-1,1]){const m=block(arrow,0x77fff4,side*.17,.9,0,.12,.04,.5);m.rotation.y=side*.65;m.material=neon(0x4dffcd)}g.add(arrow);this.animated.push(t=>arrow.position.z=2.4-((t*1.8+i*1.3)%5))}this.group.add(g);return g}
 update(time,calm){this.animated.forEach(fn=>fn(time,calm))}
}
